"""Observed scalar control against original/generated bytecode and independent cases.

This checks the experimental observed importer API, not a refinement theorem or
the ordinary CompilationModel backend. Exhaustion and EVM resource failures stay
distinct, including inputs with concrete cycle witnesses.
"""
import argparse
import hashlib
import json
from pathlib import Path

from eth_abi import encode
from eth_utils import keccak

from .anvil import Anvil
from .engine import HarnessError, SOLC, command, implementation_hashes, solc_compile, write_json
from .check_legacy_loop_source import search_path

FIXTURE = Path('Contracts/SolidityImportSmoke/LegacyObservedControl.sol')
DRIVER = Path('Contracts/SolidityImportSmoke/ObservedControlChecks.lean')
MASK = (1 << 256) - 1
MUTATIONS = ('continue-exits', 'break-repeats', 'post-skipped', 'inclusive-bound')


def cases():
    rows = []

    def add(signature, args, returns=(), values=(), status='ok', data=None, witness=None):
        types = signature.split('(', 1)[1][:-1].split(',') if args else []
        encoded = encode(types, args)
        rows.append(dict(id=str(len(rows)), function=signature.split('(')[0],
            signature=signature, args=args, words=[str(int.from_bytes(encoded[i:i+32], 'big'))
                for i in range(0, len(encoded), 32)], fuel=2000,
            calldata='0x' + (keccak(text=signature)[:4] + encoded).hex(),
            expected={'status': status, 'data': data if data is not None else
                      '0x' + encode(returns, values).hex()}, witness=witness))

    for args in [(0, 0, 0, 0, -2), (1, 0, 0, 0, -2), (5, 2, 4, 0, -2),
                 (3, 2, 2, 0, -2), (5, 2, 4, 3, -2), (5, 2, 4, 2, -2),
                 (2, 0, 0, 0, 8388607), (3, 0, 0, 0, -8388608)]:
        count, skip, stop, fail, delta = args
        last = stop if 1 <= stop <= count and stop != skip else count
        if 1 <= fail <= last:
            add('walk(uint256,uint256,uint256,uint256,int24)', args, status='revert',
                data='0x' + (keccak(text='Error(string)')[:4] + encode(['string'], ['loop'])).hex())
        else:
            total = ((last - int(1 <= skip <= last)) * delta) % (1 << 24)
            if total >= (1 << 23):
                total -= 1 << 24
            add('walk(uint256,uint256,uint256,uint256,int24)', args,
                ['int24', 'uint256'], [total, last])
    for n, skip, stop in [(0, 99, 99), (1, 99, 99), (5, 2, 4), (5, 2, 2), (5, 1, 3)]:
        end = stop + 1 if stop < n and stop != skip else n
        total = end * (end - 1) // 2 - (skip if skip < end else 0)
        add('counted(uint256,uint256,uint256)', [n, skip, stop], ['uint256'], [total])
    for n, m in [(0, 3), (1, 0), (1, 1), (3, 3)]:
        add('nested(uint256,uint256)', [n, m], ['uint256'],
            [n * int(m > 0) + 10 * (n - int(n > 1))])
    for n, stop in [(0, 0), (1, 0), (5, 3), (3, 7)]:
        visits = stop if 1 <= stop <= n else n
        tests = visits if 1 <= stop <= n else n + 1
        add('conditionEffects(uint256,uint256)', [n, stop], ['uint256', 'uint256'], [visits, tests])
    for n, target in [(0, 0), (4, 2), (4, 7)]:
        add('early(uint256,uint256)', [n, target], ['uint256'],
            [target if 1 <= target <= n else 77])
    for n, skip, stop in [(0, 0, 0), (5, 2, 4), (5, 2, 2)]:
        breaks = 1 <= stop <= n and stop != skip
        end = stop if breaks else n
        add('postEffects(uint256,uint256,uint256)', [n, skip, stop],
            ['uint256', 'uint256'], [3 * (end - int(breaks)), end])
    for n, delta in [(0, -3), (1, -3), (2, 8388607), (2, -8388608)]:
        result = 2
        for _ in range(n):
            result = (result - delta) * delta % (1 << 24)
        if result >= (1 << 23):
            result -= 1 << 24
        add('signedOps(uint256,int24)', [n, delta], ['int24'], [result])
    for args in [(0, 7, 3, 0), (0, 7, 0, 0), (0, 7, 7, 0), (0, 7, 5, 8), (0, 7, 7, MASK)]:
        witness = search_path(*args)
        if 'value' in witness:
            add('search(uint256,uint256,uint256,uint256)', args, ['uint256'], [witness['value']])
        else:
            add('search(uint256,uint256,uint256,uint256)', args, status='exhausted', witness=witness)
    add('forever()', [], status='exhausted', witness='unconditional continue with unchanged source state')
    return rows


def check(output, optimized=False, mutation=None):
    output = Path(output).resolve()
    output.mkdir(parents=True, exist_ok=False)
    source = FIXTURE.read_text()
    captured = implementation_hashes() | {
        str(path): hashlib.sha256(path.read_bytes()).hexdigest() for path in (FIXTURE, DRIVER)}
    write_json(output / 'manifest.json', {'implementation': captured,
        'solcSha256': {str(path): hashlib.sha256(path.read_bytes()).hexdigest()
                      for path in (SOLC, Path('.lake/solidity-import/solc-0.7.6'))}})
    (output / FIXTURE.name).write_text(source)
    compiled = solc_compile({'language': 'Solidity',
        'sources': {'Source.sol': {'content': source}}, 'settings': {
            'evmVersion': 'istanbul', 'optimizer': {'enabled': optimized, 'runs': 800},
            'metadata': {'bytecodeHash': 'none'}, 'outputSelection': {'*': {
                '': ['ast'], '*': ['evm.bytecode.object', 'evm.methodIdentifiers']}}}},
        output, output / 'solc', solc=Path.cwd() / '.lake/solidity-import/solc-0.7.6')
    ast = compiled['sources']['Source.sol']['ast']
    contract_ast = next(n for n in ast['nodes'] if n['nodeType'] == 'ContractDefinition')
    functions = [n for n in contract_ast['nodes'] if n['nodeType'] == 'FunctionDefinition']
    names = []

    def collect(node):
        if isinstance(node, dict):
            if isinstance(node.get('name'), str):
                names.append(node['name'])
            for value in node.values():
                collect(value)
        elif isinstance(node, list):
            for value in node:
                collect(value)

    collect(ast)
    rows = cases()
    bundle = output / 'input.json'
    write_json(bundle, dict(source=source, names=sorted(set(names)), functions=functions,
                           cases=rows, mutation=mutation or ''))
    driver = output / 'Driver.lean'
    driver.write_text(DRIVER.read_text() + '\nobserved_control_cases ' + json.dumps(str(bundle)) +
                      ' output ' + json.dumps(str(output / 'model.json')) + '\n')
    command(['turbo-lean', '--json', 'eval', str(driver), '--project-dir', '.',
             '--timeout-ms', '180000'], timeout=240, log=output / 'model.log')
    model = json.loads((output / 'model.json').read_text())
    if (model['rejected'] != ['unguarded', 'staleGuard', 'viewOnly', 'unnamedResult']
            or {r['id'] for r in model['observations']} != {r['id'] for r in rows}
            or len(model['observations']) != len(rows)):
        raise HarnessError('observed lowering coverage is incomplete')
    models = {r['id']: {'status': r['status'], 'data': r['data']} for r in model['observations']}
    contract = compiled['contracts']['Source.sol']['LegacyObservedControl']
    signatures = {row['function']: row['signature'] for row in rows}
    arms = []
    for fn in model['compiled']:
        selector = contract['evm']['methodIdentifiers'][signatures[fn['name']]]
        arms.append('case 0x' + selector + ' {\n' + fn['body'] + '\n}')
    yul = ('object "Observed" { code { datacopy(0, dataoffset("runtime"), '
           'datasize("runtime")) return(0, datasize("runtime")) } '
           'object "runtime" { code { switch shr(224, calldataload(0))\n' +
           '\n'.join(arms) + '\ndefault { revert(0, 0) } } } }')
    (output / 'observed.yul').write_text(yul)
    generated = solc_compile({'language': 'Yul', 'sources': {'Observed.yul': {'content': yul}},
        'settings': {'evmVersion': 'osaka', 'optimizer': {'enabled': optimized, 'runs': 800},
                     'outputSelection': {'*': {'*': ['evm.bytecode.object']}}}},
        output, output / 'generated-solc')['contracts']['Observed.yul']['Observed']
    failures, observations, witnesses = [], [], []
    with Anvil(output / 'node') as node:
        sender = node.rpc('eth_accounts')[0]
        accounts = {}
        for route, artifact in [('source', contract), ('generated', generated)]:
            deployed = node.transact({'from': sender,
                'data': '0x' + artifact['evm']['bytecode']['object'], 'gas': hex(3000000)})
            if deployed['receipt']['status'] != '0x1':
                raise HarnessError(f'observed-control {route} deployment failed')
            accounts[route] = deployed['receipt']['contractAddress']
        for row in rows:
            observed = dict(case=row, model=models[row['id']])
            expected_evm = dict(row['expected'])
            if expected_evm['status'] == 'exhausted':
                expected_evm['status'] = 'resource-exhausted'
            for route, account in accounts.items():
                trace = node.transact({'from': sender, 'to': account, 'data': row['calldata'],
                                       'gas': hex(150000)})
                call, receipt = trace['call'], trace['receipt']
                status = 'ok' if receipt['status'] == '0x1' else 'revert'
                if 'out of gas' in call.get('error', '').lower():
                    if receipt['status'] != '0x0' or int(receipt['gasUsed'], 16) != 150000:
                        raise HarnessError('inconsistent resource failure')
                    status = 'resource-exhausted'
                elif status == 'revert' and call.get('error') != 'execution reverted':
                    raise HarnessError(f'unexpected {route} bytecode halt')
                observed[route] = {'status': status, 'data': call.get('output', '0x')}
            if observed['source'] != expected_evm:
                failures.append(row['id'])
            elif mutation:
                # Tool errors, out-of-gas, and observer exhaustion never kill a
                # mutant. Require a completed, identical wrong source outcome
                # from both mutated routes against a correct original call.
                if (observed['model']['status'] in ('ok', 'revert')
                        and observed['model'] == observed['generated']
                        and observed['model'] != row['expected']
                        and row['expected']['status'] in ('ok', 'revert')):
                    witnesses.append(row['id'])
            elif models[row['id']] != row['expected'] or observed['generated'] != expected_evm:
                failures.append(row['id'])
            observations.append(observed)
    current = implementation_hashes() | {
        str(path): hashlib.sha256(path.read_bytes()).hexdigest() for path in (FIXTURE, DRIVER)}
    if current != captured:
        raise HarnessError('implementation changed during observed-control execution')
    passed = not failures and (not mutation or bool(witnesses))
    write_json(output / 'results.json', dict(passed=passed, failures=failures,
        mutation=mutation, completedMutationWitnesses=witnesses,
        optimized=optimized, observations=observations,
        sourceSha256=hashlib.sha256(source.encode()).hexdigest(),
        scope='canonical pure scalar call frames; observed AST versus original and generated bytecode; no theorem claim'))
    if not passed:
        raise HarnessError('observed control failed independent expectations or mutation sensitivity')
    print('observed control importer checks passed')


def run(output, optimized=False, mutation=None):
    if not mutation:
        return check(output, optimized)
    output = Path(output).resolve()
    output.mkdir(parents=True, exist_ok=False)
    # Every independently scheduled mutation requires a clean baseline with the
    # same implementation, compiler pins, profile, source and concrete cases.
    check(output / 'baseline', optimized)
    check(output / 'mutant', optimized, mutation)
    baseline = json.loads((output / 'baseline/manifest.json').read_text())
    mutant = json.loads((output / 'mutant/manifest.json').read_text())
    if baseline != mutant:
        raise HarnessError('mutation baseline identity changed')
    result = json.loads((output / 'mutant/results.json').read_text())
    write_json(output / 'results.json', dict(result, baselinePassed=True,
        baselineEvidence='baseline/results.json', mutantEvidence='mutant/results.json'))


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--optimized', action='store_true')
    parser.add_argument('--mutation', choices=MUTATIONS)
    run(**vars(parser.parse_args()))
